package com.example.myapplication.chat

import java.util.Locale

/** Bundled response templates: no network, models or translation service. */
class ChatLanguage(val code: String = "en") {
    private val index = when (code) { "as" -> 0; "bn" -> 1; "ne" -> 2; else -> -1 }
    fun text(key: String, vararg args: Any): String {
        val template = if (index < 0) english[key] ?: key else translations[key]?.get(index) ?: english[key] ?: key
        return if (args.isEmpty()) template else String.format(Locale.ROOT, template, *args)
    }
