            "sad" to "I'm sorry today feels difficult. Would you like to tell me what's on your mind, or talk with %s?",
            "visited" to "Thank you for telling me about %s's visit. What did you enjoy doing together?",
            "medicine_note" to "\nAn unchecked entry doesn't prove a dose was missed. Check with your caregiver if unsure; use Medicines to mark a confirmed dose.",
            "routine_note" to "\nOpen Daily routine to update an activity.",
            "member" to "%s is listed as your %s.",
            "note" to " Your caregiver's note says: %s",
            "share" to "Would you like to share a memory about %s?",
            "interests" to "Topics you said you enjoy: %s. Topics to avoid: %s. You can edit these in Memory.",
            "time" to "It is %s on this device.",
            "sharing" to "Thank you for sharing. %s",
            "visit_today" to "Your caregiver's note says %s visits on %ss. Has %s visited today yet?",
